{"content":"// Box with print-in-place hinge (v3: global bore subtraction, hinge cutouts)
part = "box";
cadverify_only = "";
module instance(name, part, unit = 1) {
    echo(cadverify_instance = [name, part, unit]);
    if (cadverify_only == "" || cadverify_only == name) children();
}

Rkn = 3.2; rbore = 2.2; rpin = 1.9;
yh = -30.5; zh = 30.8;         // hinge axis (box coords = assembly coords)
lid_zh = 3.4;                  // hinge axis in lid part coords
lid_lift = 27.4;               // lid part -> assembly
pin_lift_z = 27.8; pin_shift_y = -30.5;
// knuckle spans: box k0 k2 k4, lid k1 k3 (0.4 axial gaps)
k0x0=-30; k0x1=-18.32;
k1x0=-17.92; k1x1=-6.24;
k2x0=-5.84; k2x1=5.84;
k3x0=6.24; k3x1=17.92;
k4x0=18.32; k4x1=30;

$fn = 64;

module xcyl(x0, x1, r, y, z) {
    translate([x0, y, z]) rotate([0, 90, 0]) cylinder(r = r, h = x1 - x0);
}

module box_part() {
    difference() {
        union() {
            // floor + walls
            translate([-40, -30, 0]) cube([80, 60, 2.4]);
            translate([-40, 27.6, 2.4]) cube([80, 2.4, 27.6]);
            translate([-40, -30, 2.4]) cube([80, 2.4, 24.6]);      // back wall to 27.0
            translate([-40, -30, 27.0]) cube([21.88, 2.4, 3.0]);   // back top segs
            translate([-6.04, -30, 27.0]) cube([12.08, 2.4, 3.0]);
            translate([18.12, -30, 27.0]) cube([21.88, 2.4, 3.0]);
            translate([-40, -27.6, 2.4]) cube([2.4, 55.2, 27.6]);
            translate([37.6, -27.6, 2.4]) cube([2.4, 55.2, 27.6]);
            // catch bump (front inner)
            translate([-3, 27.0, 27.5]) cube([6, 0.6, 1.5]);
            // hinge knuckles + lugs
            xcyl(k0x0, k0x1, Rkn, yh, zh);
            xcyl(k2x0, k2x1, Rkn, yh, zh);
            xcyl(k4x0, k4x1, Rkn, yh, zh);
            translate([k0x0, -31, 27.6]) cube([k0x1-k0x0, 3.4, 3.2]);
            translate([k2x0, -31, 27.6]) cube([k2x1-k2x0, 3.4, 3.2]);
            translate([k4x0, -31, 27.6]) cube([k4x1-k4x0, 3.4, 3.2]);
        }
        // global bore subtraction (clears knuckles, lugs and wall intrusions)
        xcyl(k0x0-0.06, k0x1+0.06, rbore, yh, zh);
        xcyl(k2x0-0.06, k2x1+0.06, rbore, yh, zh);
        xcyl(k4x0-0.06, k4x1+0.06, rbore, yh, zh);
    }
}

module lid_part() {
